import{_ as s,c as a,a as e,o as p}from"./app-CsAvyQY4.js";const t={};function c(l,n){return p(),a("div",null,[...n[0]||(n[0]=[e(`<h1 id="mutex-и-синхронизация" tabindex="-1"><a class="header-anchor" href="#mutex-и-синхронизация"><span>Mutex и синхронизация</span></a></h1><h2 id="цель-урока" tabindex="-1"><a class="header-anchor" href="#цель-урока"><span>Цель урока</span></a></h2><p>Научиться распознавать гонки данных, защищать общее изменяемое состояние через <code>sync.Mutex</code> и <code>sync.RWMutex</code>, а также создать безопасное хранилище задач <code>TaskStore</code>.</p><p>Каналы подходят для передачи данных между goroutine. Но иногда несколько goroutine должны обращаться к одной структуре данных — например, к map задач. В этом случае доступ нужно синхронизировать мьютексом.</p><h2 id="что-такое-гонка-данных" tabindex="-1"><a class="header-anchor" href="#что-такое-гонка-данных"><span>Что такое гонка данных</span></a></h2><p>Гонка данных (data race) возникает, когда несколько goroutine одновременно обращаются к одной переменной, хотя бы одна из них пишет, и доступ не синхронизирован.</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">package</span> main</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">	<span class="token string">&quot;fmt&quot;</span></span>
<span class="line">	<span class="token string">&quot;sync&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">var</span> wg sync<span class="token punctuation">.</span>WaitGroup</span>
<span class="line">	completedExports <span class="token operator">:=</span> <span class="token number">0</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">for</span> <span class="token keyword">range</span> <span class="token number">2</span> <span class="token punctuation">{</span></span>
<span class="line">		wg<span class="token punctuation">.</span><span class="token function">Add</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">		<span class="token keyword">go</span> <span class="token keyword">func</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">			<span class="token keyword">defer</span> wg<span class="token punctuation">.</span><span class="token function">Done</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">			completedExports<span class="token operator">++</span></span>
<span class="line">		<span class="token punctuation">}</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	wg<span class="token punctuation">.</span><span class="token function">Wait</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span>completedExports<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Иногда этот пример напечатает <code>2</code>, но это не делает код корректным: две goroutine могут одновременно прочитать старое значение и записать одинаковый результат.</p><p>Проверяйте конкурентный код детектором гонок:</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code><span class="line">go run <span class="token parameter variable">-race</span> <span class="token builtin class-name">.</span></span>
<span class="line">go <span class="token builtin class-name">test</span> <span class="token parameter variable">-race</span> ./<span class="token punctuation">..</span>.</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Детектор не доказывает отсутствие всех проблем, но часто находит реальные ошибки во время выполнения тестов или программы.</p><h2 id="sync-mutex" tabindex="-1"><a class="header-anchor" href="#sync-mutex"><span><code>sync.Mutex</code></span></a></h2><p><code>sync.Mutex</code> допускает только одну goroutine в критическую секцию одновременно:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">var</span> mu sync<span class="token punctuation">.</span>Mutex</span>
<span class="line"></span>
<span class="line">mu<span class="token punctuation">.</span><span class="token function">Lock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// Работа с общими изменяемыми данными.</span></span>
<span class="line">mu<span class="token punctuation">.</span><span class="token function">Unlock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Исправим счётчик:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">package</span> main</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">	<span class="token string">&quot;fmt&quot;</span></span>
<span class="line">	<span class="token string">&quot;sync&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">var</span> wg sync<span class="token punctuation">.</span>WaitGroup</span>
<span class="line">	<span class="token keyword">var</span> mu sync<span class="token punctuation">.</span>Mutex</span>
<span class="line">	completedExports <span class="token operator">:=</span> <span class="token number">0</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">for</span> <span class="token keyword">range</span> <span class="token number">2</span> <span class="token punctuation">{</span></span>
<span class="line">		wg<span class="token punctuation">.</span><span class="token function">Add</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">		<span class="token keyword">go</span> <span class="token keyword">func</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">			<span class="token keyword">defer</span> wg<span class="token punctuation">.</span><span class="token function">Done</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">			mu<span class="token punctuation">.</span><span class="token function">Lock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">			completedExports<span class="token operator">++</span></span>
<span class="line">			mu<span class="token punctuation">.</span><span class="token function">Unlock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token punctuation">}</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	wg<span class="token punctuation">.</span><span class="token function">Wait</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span>completedExports<span class="token punctuation">)</span> <span class="token comment">// 2</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Мьютекс не хранит данные сам. Он защищает данные, с которыми договорились работать только между <code>Lock</code> и <code>Unlock</code>.</p><h2 id="defer-unlock" tabindex="-1"><a class="header-anchor" href="#defer-unlock"><span><code>defer Unlock</code></span></a></h2><p>После успешного <code>Lock</code> обычно сразу пишут <code>defer Unlock</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line">mu<span class="token punctuation">.</span><span class="token function">Lock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">defer</span> mu<span class="token punctuation">.</span><span class="token function">Unlock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Критическая секция.</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Это защищает от забытого <code>Unlock</code>, если функция выйдет раньше через <code>return</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">func</span> <span class="token function">updateTitle</span><span class="token punctuation">(</span>mu <span class="token operator">*</span>sync<span class="token punctuation">.</span>Mutex<span class="token punctuation">,</span> titles <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">int</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">,</span> id <span class="token builtin">int</span><span class="token punctuation">,</span> title <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token builtin">bool</span> <span class="token punctuation">{</span></span>
<span class="line">	mu<span class="token punctuation">.</span><span class="token function">Lock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">defer</span> mu<span class="token punctuation">.</span><span class="token function">Unlock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> <span class="token boolean">_</span><span class="token punctuation">,</span> exists <span class="token operator">:=</span> titles<span class="token punctuation">[</span>id<span class="token punctuation">]</span><span class="token punctuation">;</span> <span class="token operator">!</span>exists <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> <span class="token boolean">false</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	titles<span class="token punctuation">[</span>id<span class="token punctuation">]</span> <span class="token operator">=</span> title</span>
<span class="line">	<span class="token keyword">return</span> <span class="token boolean">true</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Не вызывайте <code>defer mu.Unlock()</code> до <code>mu.Lock()</code>: будет попытка разблокировать незаблокированный мьютекс и panic.</p><h2 id="taskstore-общее-хранилище-задач" tabindex="-1"><a class="header-anchor" href="#taskstore-общее-хранилище-задач"><span>TaskStore: общее хранилище задач</span></a></h2><p>Создадим структуру, которая хранит map задач и защищает её мьютексом:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">type</span> TaskStore <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	mu    sync<span class="token punctuation">.</span>RWMutex</span>
<span class="line">	tasks <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">int</span><span class="token punctuation">]</span>task<span class="token punctuation">.</span>Task</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Мьютекс делают полем той же структуры, что и защищаемые данные. Так легче увидеть правило: поле <code>tasks</code> читается и меняется только через методы <code>TaskStore</code>.</p><p>Конструктор создаёт готовое к работе хранилище:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">func</span> <span class="token function">NewTaskStore</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">*</span>TaskStore <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> <span class="token operator">&amp;</span>TaskStore<span class="token punctuation">{</span></span>
<span class="line">		tasks<span class="token punctuation">:</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">int</span><span class="token punctuation">]</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Возвращаем указатель на <code>TaskStore</code>: мьютекс нельзя копировать после первого использования, а всем goroutine нужно обращаться к одному хранилищу.</p><h2 id="запись-lock" tabindex="-1"><a class="header-anchor" href="#запись-lock"><span>Запись: <code>Lock</code></span></a></h2><p>Метод <code>Add</code> меняет map, поэтому использует <code>Lock</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">var</span> ErrTaskAlreadyExists <span class="token operator">=</span> errors<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span><span class="token string">&quot;задача с таким ID уже существует&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>store <span class="token operator">*</span>TaskStore<span class="token punctuation">)</span> <span class="token function">Add</span><span class="token punctuation">(</span>currentTask task<span class="token punctuation">.</span>Task<span class="token punctuation">)</span> <span class="token builtin">error</span> <span class="token punctuation">{</span></span>
<span class="line">	store<span class="token punctuation">.</span>mu<span class="token punctuation">.</span><span class="token function">Lock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">defer</span> store<span class="token punctuation">.</span>mu<span class="token punctuation">.</span><span class="token function">Unlock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> <span class="token boolean">_</span><span class="token punctuation">,</span> exists <span class="token operator">:=</span> store<span class="token punctuation">.</span>tasks<span class="token punctuation">[</span>currentTask<span class="token punctuation">.</span>ID<span class="token punctuation">]</span><span class="token punctuation">;</span> exists <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> ErrTaskAlreadyExists</span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	store<span class="token punctuation">.</span>tasks<span class="token punctuation">[</span>currentTask<span class="token punctuation">.</span>ID<span class="token punctuation">]</span> <span class="token operator">=</span> currentTask</span>
<span class="line">	<span class="token keyword">return</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Проверка наличия ключа и добавление выполняются под одним мьютексом. Если разблокировать map между этими действиями, другая goroutine сможет добавить задачу с тем же ID.</p><h2 id="чтение-rlock" tabindex="-1"><a class="header-anchor" href="#чтение-rlock"><span>Чтение: <code>RLock</code></span></a></h2><p><code>sync.RWMutex</code> расширяет обычный мьютекс:</p><ul><li><code>Lock</code> / <code>Unlock</code> — эксклюзивный доступ для записи;</li><li><code>RLock</code> / <code>RUnlock</code> — совместный доступ для чтения несколькими goroutine.</li></ul><p>Метод <code>Get</code> только читает map:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>store <span class="token operator">*</span>TaskStore<span class="token punctuation">)</span> <span class="token function">Get</span><span class="token punctuation">(</span>id <span class="token builtin">int</span><span class="token punctuation">)</span> <span class="token punctuation">(</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">,</span> <span class="token builtin">bool</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	store<span class="token punctuation">.</span>mu<span class="token punctuation">.</span><span class="token function">RLock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">defer</span> store<span class="token punctuation">.</span>mu<span class="token punctuation">.</span><span class="token function">RUnlock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	currentTask<span class="token punctuation">,</span> exists <span class="token operator">:=</span> store<span class="token punctuation">.</span>tasks<span class="token punctuation">[</span>id<span class="token punctuation">]</span></span>
<span class="line">	<span class="token keyword">return</span> currentTask<span class="token punctuation">,</span> exists</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Несколько читателей могут работать одновременно. Но если идёт запись через <code>Lock</code>, новые читатели и писатели подождут.</p><p>Для небольшого проекта можно начать с <code>sync.Mutex</code> для всех операций. <code>RWMutex</code> полезен, когда чтений заметно больше, чем записей, и только после измерений или понятной причины. Здесь он нужен для знакомства с разделением чтения и записи.</p><h2 id="изменение-задачи-в-taskstore" tabindex="-1"><a class="header-anchor" href="#изменение-задачи-в-taskstore"><span>Изменение задачи в TaskStore</span></a></h2><p>Задача хранится в map значением. Поэтому получаем копию, меняем её и сохраняем обратно — всё под одним <code>Lock</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">var</span> ErrTaskNotFound <span class="token operator">=</span> errors<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span><span class="token string">&quot;задача не найдена&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>store <span class="token operator">*</span>TaskStore<span class="token punctuation">)</span> <span class="token function">Rename</span><span class="token punctuation">(</span>id <span class="token builtin">int</span><span class="token punctuation">,</span> title <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token builtin">error</span> <span class="token punctuation">{</span></span>
<span class="line">	store<span class="token punctuation">.</span>mu<span class="token punctuation">.</span><span class="token function">Lock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">defer</span> store<span class="token punctuation">.</span>mu<span class="token punctuation">.</span><span class="token function">Unlock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	currentTask<span class="token punctuation">,</span> exists <span class="token operator">:=</span> store<span class="token punctuation">.</span>tasks<span class="token punctuation">[</span>id<span class="token punctuation">]</span></span>
<span class="line">	<span class="token keyword">if</span> <span class="token operator">!</span>exists <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> ErrTaskNotFound</span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> err <span class="token operator">:=</span> currentTask<span class="token punctuation">.</span><span class="token function">Rename</span><span class="token punctuation">(</span>title<span class="token punctuation">)</span><span class="token punctuation">;</span> err <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> err</span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	store<span class="token punctuation">.</span>tasks<span class="token punctuation">[</span>id<span class="token punctuation">]</span> <span class="token operator">=</span> currentTask</span>
<span class="line">	<span class="token keyword">return</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Метод <code>Complete</code> устроен так же:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>store <span class="token operator">*</span>TaskStore<span class="token punctuation">)</span> <span class="token function">Complete</span><span class="token punctuation">(</span>id <span class="token builtin">int</span><span class="token punctuation">)</span> <span class="token builtin">error</span> <span class="token punctuation">{</span></span>
<span class="line">	store<span class="token punctuation">.</span>mu<span class="token punctuation">.</span><span class="token function">Lock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">defer</span> store<span class="token punctuation">.</span>mu<span class="token punctuation">.</span><span class="token function">Unlock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	currentTask<span class="token punctuation">,</span> exists <span class="token operator">:=</span> store<span class="token punctuation">.</span>tasks<span class="token punctuation">[</span>id<span class="token punctuation">]</span></span>
<span class="line">	<span class="token keyword">if</span> <span class="token operator">!</span>exists <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> ErrTaskNotFound</span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	currentTask<span class="token punctuation">.</span><span class="token function">Complete</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	store<span class="token punctuation">.</span>tasks<span class="token punctuation">[</span>id<span class="token punctuation">]</span> <span class="token operator">=</span> currentTask</span>
<span class="line">	<span class="token keyword">return</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="полныи-пример" tabindex="-1"><a class="header-anchor" href="#полныи-пример"><span>Полный пример</span></a></h2><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">package</span> main</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">	<span class="token string">&quot;errors&quot;</span></span>
<span class="line">	<span class="token string">&quot;fmt&quot;</span></span>
<span class="line">	<span class="token string">&quot;sync&quot;</span></span>
<span class="line"></span>
<span class="line">	<span class="token string">&quot;example.com/task-manager/internal/task&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">var</span> <span class="token punctuation">(</span></span>
<span class="line">	ErrTaskNotFound      <span class="token operator">=</span> errors<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span><span class="token string">&quot;задача не найдена&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	ErrTaskAlreadyExists <span class="token operator">=</span> errors<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span><span class="token string">&quot;задача с таким ID уже существует&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> TaskStore <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	mu    sync<span class="token punctuation">.</span>RWMutex</span>
<span class="line">	tasks <span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">int</span><span class="token punctuation">]</span>task<span class="token punctuation">.</span>Task</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">NewTaskStore</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">*</span>TaskStore <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> <span class="token operator">&amp;</span>TaskStore<span class="token punctuation">{</span>tasks<span class="token punctuation">:</span> <span class="token function">make</span><span class="token punctuation">(</span><span class="token keyword">map</span><span class="token punctuation">[</span><span class="token builtin">int</span><span class="token punctuation">]</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">)</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>store <span class="token operator">*</span>TaskStore<span class="token punctuation">)</span> <span class="token function">Add</span><span class="token punctuation">(</span>currentTask task<span class="token punctuation">.</span>Task<span class="token punctuation">)</span> <span class="token builtin">error</span> <span class="token punctuation">{</span></span>
<span class="line">	store<span class="token punctuation">.</span>mu<span class="token punctuation">.</span><span class="token function">Lock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">defer</span> store<span class="token punctuation">.</span>mu<span class="token punctuation">.</span><span class="token function">Unlock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> <span class="token boolean">_</span><span class="token punctuation">,</span> exists <span class="token operator">:=</span> store<span class="token punctuation">.</span>tasks<span class="token punctuation">[</span>currentTask<span class="token punctuation">.</span>ID<span class="token punctuation">]</span><span class="token punctuation">;</span> exists <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> ErrTaskAlreadyExists</span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	store<span class="token punctuation">.</span>tasks<span class="token punctuation">[</span>currentTask<span class="token punctuation">.</span>ID<span class="token punctuation">]</span> <span class="token operator">=</span> currentTask</span>
<span class="line">	<span class="token keyword">return</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>store <span class="token operator">*</span>TaskStore<span class="token punctuation">)</span> <span class="token function">Get</span><span class="token punctuation">(</span>id <span class="token builtin">int</span><span class="token punctuation">)</span> <span class="token punctuation">(</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">,</span> <span class="token builtin">bool</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	store<span class="token punctuation">.</span>mu<span class="token punctuation">.</span><span class="token function">RLock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">defer</span> store<span class="token punctuation">.</span>mu<span class="token punctuation">.</span><span class="token function">RUnlock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	currentTask<span class="token punctuation">,</span> exists <span class="token operator">:=</span> store<span class="token punctuation">.</span>tasks<span class="token punctuation">[</span>id<span class="token punctuation">]</span></span>
<span class="line">	<span class="token keyword">return</span> currentTask<span class="token punctuation">,</span> exists</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>store <span class="token operator">*</span>TaskStore<span class="token punctuation">)</span> <span class="token function">Complete</span><span class="token punctuation">(</span>id <span class="token builtin">int</span><span class="token punctuation">)</span> <span class="token builtin">error</span> <span class="token punctuation">{</span></span>
<span class="line">	store<span class="token punctuation">.</span>mu<span class="token punctuation">.</span><span class="token function">Lock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token keyword">defer</span> store<span class="token punctuation">.</span>mu<span class="token punctuation">.</span><span class="token function">Unlock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	currentTask<span class="token punctuation">,</span> exists <span class="token operator">:=</span> store<span class="token punctuation">.</span>tasks<span class="token punctuation">[</span>id<span class="token punctuation">]</span></span>
<span class="line">	<span class="token keyword">if</span> <span class="token operator">!</span>exists <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">return</span> ErrTaskNotFound</span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">	currentTask<span class="token punctuation">.</span><span class="token function">Complete</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	store<span class="token punctuation">.</span>tasks<span class="token punctuation">[</span>id<span class="token punctuation">]</span> <span class="token operator">=</span> currentTask</span>
<span class="line">	<span class="token keyword">return</span> <span class="token boolean">nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">	store <span class="token operator">:=</span> <span class="token function">NewTaskStore</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token boolean">_</span> <span class="token operator">=</span> store<span class="token punctuation">.</span><span class="token function">Add</span><span class="token punctuation">(</span>task<span class="token punctuation">.</span>Task<span class="token punctuation">{</span>ID<span class="token punctuation">:</span> <span class="token number">1</span><span class="token punctuation">,</span> Title<span class="token punctuation">:</span> <span class="token string">&quot;Купить молоко&quot;</span><span class="token punctuation">,</span> Priority<span class="token punctuation">:</span> <span class="token number">2</span><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">var</span> wg sync<span class="token punctuation">.</span>WaitGroup</span>
<span class="line">	wg<span class="token punctuation">.</span><span class="token function">Add</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">go</span> <span class="token keyword">func</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">defer</span> wg<span class="token punctuation">.</span><span class="token function">Done</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token boolean">_</span> <span class="token operator">=</span> store<span class="token punctuation">.</span><span class="token function">Complete</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">go</span> <span class="token keyword">func</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">		<span class="token keyword">defer</span> wg<span class="token punctuation">.</span><span class="token function">Done</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">		<span class="token boolean">_</span><span class="token punctuation">,</span> <span class="token boolean">_</span> <span class="token operator">=</span> store<span class="token punctuation">.</span><span class="token function">Get</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	wg<span class="token punctuation">.</span><span class="token function">Wait</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">	<span class="token keyword">if</span> currentTask<span class="token punctuation">,</span> exists <span class="token operator">:=</span> store<span class="token punctuation">.</span><span class="token function">Get</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span> exists <span class="token punctuation">{</span></span>
<span class="line">		fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span>currentTask<span class="token punctuation">.</span><span class="token function">Summary</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Для краткости в <code>main</code> ошибки методов игнорируются через <code>_</code>. В реальном приложении их нужно обрабатывать; в практических заданиях ниже это будет сделано явно.</p><h2 id="waitgroup-и-mutex-решают-разные-задачи" tabindex="-1"><a class="header-anchor" href="#waitgroup-и-mutex-решают-разные-задачи"><span>WaitGroup и Mutex решают разные задачи</span></a></h2><p>Эти инструменты часто используются вместе, но отвечают на разные вопросы:</p><table><thead><tr><th>Инструмент</th><th>Вопрос</th></tr></thead><tbody><tr><td><code>sync.WaitGroup</code></td><td>«Когда все goroutine закончили?»</td></tr><tr><td><code>sync.Mutex</code> / <code>sync.RWMutex</code></td><td>«Кто сейчас может обратиться к общим изменяемым данным?»</td></tr><tr><td>Канал</td><td>«Как передать значение или сигнал между goroutine?»</td></tr></tbody></table><p><code>WaitGroup</code> не делает map безопасной, а мьютекс не ждёт завершения goroutine.</p><h2 id="не-копируите-mutex-и-rwmutex" tabindex="-1"><a class="header-anchor" href="#не-копируите-mutex-и-rwmutex"><span>Не копируйте Mutex и RWMutex</span></a></h2><p>Не копируйте <code>TaskStore</code> после того, как он начал использоваться:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line">store <span class="token operator">:=</span> <span class="token function">NewTaskStore</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token comment">// copiedStore := *store // нельзя: копируется уже используемый RWMutex</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>Передавайте <code>*TaskStore</code> в функции и храните один экземпляр хранилища. Правило аналогично <code>WaitGroup</code>: объекты синхронизации используют через указатель.</p><h2 id="не-держите-мьютекс-во-время-медленнои-работы" tabindex="-1"><a class="header-anchor" href="#не-держите-мьютекс-во-время-медленнои-работы"><span>Не держите мьютекс во время медленной работы</span></a></h2><p>Критическая секция должна быть короткой. Не выполняйте запись файла, HTTP-запрос или долгие вычисления под <code>Lock</code>:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token comment">// Плохо: остальные goroutine не смогут работать с store,</span></span>
<span class="line"><span class="token comment">// пока выполняется медленный экспорт.</span></span>
<span class="line"><span class="token comment">// store.mu.Lock()</span></span>
<span class="line"><span class="token comment">// exportJSON(&quot;tasks.json&quot;, tasks)</span></span>
<span class="line"><span class="token comment">// store.mu.Unlock()</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Сначала под блокировкой получите нужные данные, затем разблокируйте хранилище и выполняйте медленную работу отдельно. Создание безопасной копии списка задач разберём, когда TaskStore получит метод <code>List</code>.</p><h2 id="частые-ошибки" tabindex="-1"><a class="header-anchor" href="#частые-ошибки"><span>Частые ошибки</span></a></h2><h3 id="открыть-без-закрытия" tabindex="-1"><a class="header-anchor" href="#открыть-без-закрытия"><span>Открыть без закрытия</span></a></h3><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line">store<span class="token punctuation">.</span>mu<span class="token punctuation">.</span><span class="token function">Lock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> task<span class="token punctuation">.</span>ID <span class="token operator">&lt;=</span> <span class="token number">0</span> <span class="token punctuation">{</span></span>
<span class="line">	<span class="token keyword">return</span> errors<span class="token punctuation">.</span><span class="token function">New</span><span class="token punctuation">(</span><span class="token string">&quot;некорректный ID&quot;</span><span class="token punctuation">)</span> <span class="token comment">// Unlock не вызван</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>После <code>Lock</code> сразу используйте <code>defer store.mu.Unlock()</code>.</p><h3 id="использовать-rlock-для-записи" tabindex="-1"><a class="header-anchor" href="#использовать-rlock-для-записи"><span>Использовать <code>RLock</code> для записи</span></a></h3><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line">store<span class="token punctuation">.</span>mu<span class="token punctuation">.</span><span class="token function">RLock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">store<span class="token punctuation">.</span>tasks<span class="token punctuation">[</span>id<span class="token punctuation">]</span> <span class="token operator">=</span> currentTask <span class="token comment">// ошибка логики: RLock только для чтения</span></span>
<span class="line">store<span class="token punctuation">.</span>mu<span class="token punctuation">.</span><span class="token function">RUnlock</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Любое изменение map требует <code>Lock</code>.</p><h3 id="записать-в-map-из-нескольких-goroutine-без-мьютекса" tabindex="-1"><a class="header-anchor" href="#записать-в-map-из-нескольких-goroutine-без-мьютекса"><span>Записать в map из нескольких goroutine без мьютекса</span></a></h3><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token comment">// store.tasks[id] = currentTask // опасно без Lock</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Map не поддерживает конкурентное чтение и запись без синхронизации. Используйте методы <code>TaskStore</code> и проверяйте программу с <code>-race</code>.</p><h3 id="копировать-mutex" tabindex="-1"><a class="header-anchor" href="#копировать-mutex"><span>Копировать Mutex</span></a></h3><p>Не передавайте <code>sync.Mutex</code>, <code>sync.RWMutex</code> и <code>sync.WaitGroup</code> по значению после первого использования. Передавайте указатель на структуру, которая их содержит.</p><h2 id="дальше" tabindex="-1"><a class="header-anchor" href="#дальше"><span>Дальше</span></a></h2><p>Закрепите безопасный <code>TaskStore</code> на практике. Затем перейдём к <code>context</code>: он позволит отменять долгие операции и передавать дедлайны по цепочке вызовов.</p>`,75)])])}const i=s(t,[["render",c]]),u=JSON.parse('{"path":"/guide/mutex-and-synchronization/","title":"Mutex и синхронизация","lang":"ru-RU","frontmatter":{"prev":"/guide/select-and-timeouts/practice.md","next":"/guide/mutex-and-synchronization/tests.md"},"headers":[{"level":2,"title":"Цель урока","slug":"цель-урока","link":"#цель-урока","children":[]},{"level":2,"title":"Что такое гонка данных","slug":"что-такое-гонка-данных","link":"#что-такое-гонка-данных","children":[]},{"level":2,"title":"sync.Mutex","slug":"sync-mutex","link":"#sync-mutex","children":[]},{"level":2,"title":"defer Unlock","slug":"defer-unlock","link":"#defer-unlock","children":[]},{"level":2,"title":"TaskStore: общее хранилище задач","slug":"taskstore-общее-хранилище-задач","link":"#taskstore-общее-хранилище-задач","children":[]},{"level":2,"title":"Запись: Lock","slug":"запись-lock","link":"#запись-lock","children":[]},{"level":2,"title":"Чтение: RLock","slug":"чтение-rlock","link":"#чтение-rlock","children":[]},{"level":2,"title":"Изменение задачи в TaskStore","slug":"изменение-задачи-в-taskstore","link":"#изменение-задачи-в-taskstore","children":[]},{"level":2,"title":"Полный пример","slug":"полныи-пример","link":"#полныи-пример","children":[]},{"level":2,"title":"WaitGroup и Mutex решают разные задачи","slug":"waitgroup-и-mutex-решают-разные-задачи","link":"#waitgroup-и-mutex-решают-разные-задачи","children":[]},{"level":2,"title":"Не копируйте Mutex и RWMutex","slug":"не-копируите-mutex-и-rwmutex","link":"#не-копируите-mutex-и-rwmutex","children":[]},{"level":2,"title":"Не держите мьютекс во время медленной работы","slug":"не-держите-мьютекс-во-время-медленнои-работы","link":"#не-держите-мьютекс-во-время-медленнои-работы","children":[]},{"level":2,"title":"Частые ошибки","slug":"частые-ошибки","link":"#частые-ошибки","children":[{"level":3,"title":"Открыть без закрытия","slug":"открыть-без-закрытия","link":"#открыть-без-закрытия","children":[]},{"level":3,"title":"Использовать RLock для записи","slug":"использовать-rlock-для-записи","link":"#использовать-rlock-для-записи","children":[]},{"level":3,"title":"Записать в map из нескольких goroutine без мьютекса","slug":"записать-в-map-из-нескольких-goroutine-без-мьютекса","link":"#записать-в-map-из-нескольких-goroutine-без-мьютекса","children":[]},{"level":3,"title":"Копировать Mutex","slug":"копировать-mutex","link":"#копировать-mutex","children":[]}]},{"level":2,"title":"Дальше","slug":"дальше","link":"#дальше","children":[]}],"git":{"updatedTime":1791822967000,"contributors":[{"name":"Danil Chugaev","username":"","email":"danilchugaev@mail.ru","commits":1}],"changelog":[{"hash":"0b168e13ef01e2501c62f213fba575677d574694","time":1791822967000,"email":"danilchugaev@mail.ru","author":"Danil Chugaev","message":"docs: renamed headings"}]},"filePathRelative":"guide/mutex-and-synchronization/README.md"}');export{i as comp,u as data};
